    def hept_config(z1, z2, r1, r2, tw):
        P = []
        for zz, rr, off in ((z1, r1, 0.0), (z2, r2, tw)):
            for i in range(7):
                a = 2 * np.pi * i / 7 + off
                P.append([rr * np.cos(a), rr * np.sin(a), zz])
        return np.array(P, dtype=float)

